<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
  :root {
    --bg: #f4f5f7;
    --col-bg: #ebecf0;
    --card-bg: #ffffff;
    --accent: #5b7fff;
    --text: #172b4d;
    --muted: #6b778c;
    --shadow: 0 1px 2px rgba(9,30,66,.18);
    --shadow-hover: 0 4px 12px rgba(9,30,66,.25);
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    min-height: 100vh;
  }
  header.app-header {
    padding: 20px 28px 4px;
  }
  header.app-header h1 {
    margin: 0;
    font-size: 22px;
    font-weight: 700;
    letter-spacing: .2px;
  }
  .toolbar {
    display: flex;
    gap: 10px;
    padding: 14px 28px 20px;
    align-items: center;
  }
  #new-card {
    flex: 0 1 340px;
    padding: 10px 14px;
    border: 1px solid #dfe1e6;
    border-radius: 8px;
    font-size: 14px;
    background: #fff;
    outline: none;
    transition: border-color .15s, box-shadow .15s;
  }
  #new-card:focus {
    border-color: var(--accent);
    box-shadow: 0 0 0 3px rgba(91,127,255,.18);
  }
  #add-card {
    padding: 10px 18px;
    border: none;
    border-radius: 8px;
    background: var(--accent);
    color: #fff;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: background .15s, transform .05s;
  }
  #add-card:hover { background: #4a6bf0; }
  #add-card:active { transform: translateY(1px); }

  .board {
    display: flex;
    gap: 18px;
    padding: 4px 28px 40px;
    align-items: flex-start;
    overflow-x: auto;
  }
  .column {
    flex: 1 1 0;
    min-width: 260px;
    background: var(--col-bg);
    border-radius: 12px;
    padding: 12px;
    display: flex;
    flex-direction: column;
    transition: background .15s, box-shadow .15s;
  }
  .column.drag-over {
    background: #dfe4ee;
    box-shadow: inset 0 0 0 2px var(--accent);
  }
  .column-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 4px 8px 12px;
  }
  .column-header h2 {
    margin: 0;
    font-size: 13px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .6px;
    color: var(--muted);
  }
  .count {
    min-width: 22px;
    height: 22px;
    padding: 0 7px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: #d6d9e0;
    color: var(--muted);
    border-radius: 11px;
    font-size: 12px;
    font-weight: 700;
  }
  .cards {
    display: flex;
    flex-direction: column;
    gap: 10px;
    min-height: 40px;
    flex: 1;
  }
  .card {
    background: var(--card-bg);
    border-radius: 8px;
    padding: 12px 34px 12px 12px;
    box-shadow: var(--shadow);
    font-size: 14px;
    line-height: 1.4;
    cursor: grab;
    position: relative;
    word-break: break-word;
    transition: box-shadow .15s, transform .05s, opacity .15s;
  }
  .card:hover { box-shadow: var(--shadow-hover); }
  .card.dragging { opacity: .45; cursor: grabbing; }
  .card-title { display: block; }
  .card-del {
    position: absolute;
    top: 6px;
    right: 6px;
    width: 22px;
    height: 22px;
    border: none;
    border-radius: 6px;
    background: transparent;
    color: var(--muted);
    font-size: 16px;
    line-height: 1;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background .15s, color .15s;
  }
  .card-del:hover { background: #ffe0e0; color: #d94040; }
  .empty-hint {
    color: #a5adba;
    font-size: 12px;
    text-align: center;
    padding: 8px 0;
    font-style: italic;
    user-select: none;
  }
</style>
</head>
<body>
  <header class="app-header">
    <h1>Kanban Board</h1>
  </header>

  <div class="toolbar">
    <input id="new-card" type="text" placeholder="What needs doing?" autocomplete="off">
    <button id="add-card">Add card</button>
  </div>

  <main class="board">
    <section class="column" id="col-todo" data-col="todo">
      <div class="column-header">
        <h2>To Do</h2>
        <span class="count">0</span>
      </div>
      <div class="cards"></div>
    </section>

    <section class="column" id="col-doing" data-col="doing">
      <div class="column-header">
        <h2>Doing</h2>
        <span class="count">0</span>
      </div>
      <div class="cards"></div>
    </section>

    <section class="column" id="col-done" data-col="done">
      <div class="column-header">
        <h2>Done</h2>
        <span class="count">0</span>
      </div>
      <div class="cards"></div>
    </section>
  </main>

<script>
(function () {
  "use strict";

  var STORAGE_KEY = "kanban-board-state-v1";
  var COLUMNS = ["todo", "doing", "done"];

  // state: array of { id, title, col }
  var state = load();
  var nextId = state.reduce(function (m, c) { return Math.max(m, c.id); }, 0) + 1;

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(function (c) {
        return c && typeof c.title === "string" && COLUMNS.indexOf(c.col) !== -1;
      }).map(function (c, i) {
        return { id: typeof c.id === "number" ? c.id : i + 1, title: c.title, col: c.col };
      });
    } catch (e) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (e) { /* ignore quota / disabled storage */ }
  }

  function colContainer(col) {
    return document.querySelector("#col-" + col + " .cards");
  }
  function colCountEl(col) {
    return document.querySelector("#col-" + col + " .count");
  }

  function makeCardEl(card) {
    var el = document.createElement("div");
    el.className = "card";
    el.setAttribute("draggable", "true");
    el.dataset.id = String(card.id);

    var title = document.createElement("span");
    title.className = "card-title";
    title.textContent = card.title;
    el.appendChild(title);

    var del = document.createElement("button");
    del.className = "card-del";
    del.type = "button";
    del.setAttribute("aria-label", "Delete card");
    del.textContent = "\u00D7";
    del.addEventListener("click", function (ev) {
      ev.stopPropagation();
      deleteCard(card.id);
    });
    el.appendChild(del);

    el.addEventListener("dragstart", function (ev) {
      ev.dataTransfer.effectAllowed = "move";
      ev.dataTransfer.setData("text/plain", String(card.id));
      el.classList.add("dragging");
    });
    el.addEventListener("dragend", function () {
      el.classList.remove("dragging");
    });

    return el;
  }

  function render() {
    COLUMNS.forEach(function (col) {
      var container = colContainer(col);
      container.innerHTML = "";
      var cards = state.filter(function (c) { return c.col === col; });
      cards.forEach(function (card) {
        container.appendChild(makeCardEl(card));
      });
      if (cards.length === 0) {
        var hint = document.createElement("div");
        hint.className = "empty-hint";
        hint.textContent = "No cards";
        container.appendChild(hint);
      }
      colCountEl(col).textContent = String(cards.length);
    });
  }

  function addCard(title) {
    var text = title.trim();
    if (!text) return;
    state.push({ id: nextId++, title: text, col: "todo" });
    save();
    render();
  }

  function deleteCard(id) {
    state = state.filter(function (c) { return c.id !== id; });
    save();
    render();
  }

  function moveCard(id, col) {
    if (COLUMNS.indexOf(col) === -1) return;
    var card = state.filter(function (c) { return c.id === id; })[0];
    if (!card || card.col === col) return;
    card.col = col;
    save();
    render();
  }

  // --- Toolbar wiring ---
  var input = document.getElementById("new-card");
  var addBtn = document.getElementById("add-card");

  addBtn.addEventListener("click", function () {
    addCard(input.value);
    input.value = "";
    input.focus();
  });
  input.addEventListener("keydown", function (ev) {
    if (ev.key === "Enter") {
      addCard(input.value);
      input.value = "";
    }
  });

  // --- Drag-and-drop on columns ---
  COLUMNS.forEach(function (col) {
    var column = document.getElementById("col-" + col);

    column.addEventListener("dragover", function (ev) {
      ev.preventDefault();
      ev.dataTransfer.dropEffect = "move";
      column.classList.add("drag-over");
    });
    column.addEventListener("dragenter", function (ev) {
      ev.preventDefault();
      column.classList.add("drag-over");
    });
    column.addEventListener("dragleave", function (ev) {
      if (!column.contains(ev.relatedTarget)) {
        column.classList.remove("drag-over");
      }
    });
    column.addEventListener("drop", function (ev) {
      ev.preventDefault();
      column.classList.remove("drag-over");
      var id = parseInt(ev.dataTransfer.getData("text/plain"), 10);
      if (!isNaN(id)) moveCard(id, col);
    });
  });

  render();
})();
</script>
</body>
</html>
